PRAGMA foreign_keys = ON;
CREATE TABLE offers (id TEXT PRIMARY KEY, title TEXT NOT NULL, price_cents INTEGER NOT NULL CHECK(price_cents > 0), promise_text TEXT NOT NULL, rule_json TEXT NOT NULL, window_start TEXT NOT NULL, window_end TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE promises (id TEXT PRIMARY KEY, offer_id TEXT NOT NULL REFERENCES offers(id), paypal_order_id TEXT UNIQUE, paypal_capture_id TEXT UNIQUE, captured_cents INTEGER, status TEXT NOT NULL DEFAULT 'pending', mode TEXT NOT NULL DEFAULT 'demo', evidence_json TEXT, evidence_simulated INTEGER NOT NULL DEFAULT 0, refund_cents INTEGER, paypal_refund_id TEXT, explanation_buyer TEXT, explanation_seller TEXT, workflow_id TEXT, settlement_owner TEXT, capture_verified INTEGER DEFAULT 0, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), settled_at TEXT);
CREATE TABLE events (id INTEGER PRIMARY KEY AUTOINCREMENT, promise_id TEXT NOT NULL REFERENCES promises(id), kind TEXT NOT NULL, detail_json TEXT NOT NULL, dedupe_key TEXT UNIQUE, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX promises_status ON promises(status);
CREATE INDEX events_promise ON events(promise_id, id);
